const envelope = $json;
if (!envelope || envelope.type !== 'event.announcement_due' || envelope.version !== 1) throw new Error('Unsupported CrowdRelay event');
const data = envelope.data ?? {};
if (!data.fan?.email || !data.event?.slug || !data.event?.title || !data.event?.starts_at) throw new Error('Missing announcement fields');
const base = ("https://virya.music" || 'https://virya.music').replace(/\/$/, '');
const polish = String(data.fan.locale || 'pl').toLowerCase().startsWith('pl');
const eventPath = `${polish ? '/pl' : ''}/live/${encodeURIComponent(data.event.slug)}/`;
const addTrigger = (value, trigger) => { try { const u = new URL(value); u.searchParams.set('trigger', trigger); return u.toString(); } catch { return null; } };
const eventUrl = `${base}${eventPath}`;
const rsvpUrl = addTrigger(data.event.bandsintown_event_url, 'rsvp_going');
const followUrl = ("https://www.bandsintown.com/a/15587796-virya" || 'https://www.bandsintown.com/a/15587796-virya?trigger=track');
return [{ json: { event_id: envelope.id, mail: {
  template: 'crowdrelay-new-gig', to: data.fan.email,
  variables: { display_name: data.fan.display_name ?? null, locale: data.fan.locale ?? 'pl-PL', event_title: data.event.title, event_description: data.event.description ?? null, starts_at: data.event.starts_at, venue: data.event.venue ?? null, venue_address: data.event.venue_address ?? null, city: data.event.city ?? null, event_url: eventUrl, ticket_url: eventUrl + '#tickets', rsvp_url: rsvpUrl, follow_url: followUrl },
  idempotency_key: envelope.id
} } }];

